import sys
from collections import deque

data = sys.stdin.buffer.read().split()
n, m = map(int, data[:2])
grid = [bytearray(row) for row in data[2:2 + n]]

q = deque()
for i in range(n):
    for j in range(m):
        if grid[i][j] == ord('o'):
            q.append(i * m + j)

while q:
    pos = q.popleft()
    i, j = divmod(pos, m)

    if i + 1 < n:
        if grid[i + 1][j] == ord('.'):
            grid[i + 1][j] = ord('o')
            q.append((i + 1) * m + j)

        if grid[i + 1][j] == ord('#'):
            if j > 0 and grid[i][j - 1] == ord('.'):
                grid[i][j - 1] = ord('o')
                q.append(i * m + j - 1)
            if j + 1 < m and grid[i][j + 1] == ord('.'):
                grid[i][j + 1] = ord('o')
                q.append(i * m + j + 1)

sys.stdout.buffer.write(b'\n'.join(grid) + b'\n')
